from collections import deque

class QueueStack:
    def __init__(self):
        self.q = deque()

    def push(self, x: int) -> None:
        self.q.append(x)

    def _bring_newest_forward(self):
        for _ in range(len(self.q) - 1):
            self.q.append(self.q.popleft())

    def pop(self) -> int:
        self._bring_newest_forward()
        return self.q.popleft()

    def top(self) -> int:
        self._bring_newest_forward()
        value = self.q.popleft()
        self.q.append(value)
        return value

    def empty(self) -> bool:
        return not self.q

