class QueueStack {
    private final ArrayDeque<Integer> q = new ArrayDeque<>();

    public QueueStack() {
    }

    public void push(int x) {
        q.offer(x);
    }

    private void bringNewestForward() {
        for (int i = 0; i < q.size() - 1; i++) q.offer(q.poll());
    }

    public int pop() {
        bringNewestForward();
        return q.poll();
    }

    public int top() {
        bringNewestForward();
        int value = q.poll();
        q.offer(value);
        return value;
    }

    public boolean empty() {
        return q.isEmpty();
    }
}

